class Solution {
    public long maxSum(List<Integer> nums,int m,int k){
        Map<Integer,Integer> frequency=new HashMap<>();
        long sum=0,answer=0;
        for(int right=0;right<nums.size();right++){
            int value=nums.get(right);
            sum+=value;
            frequency.put(value,frequency.getOrDefault(value,0)+1);
            if(right>=k){
                int removed=nums.get(right-k);
                sum-=removed;
                int count=frequency.get(removed)-1;
                if(count==0)frequency.remove(removed);
                else frequency.put(removed,count);
            }
            if(right>=k-1&&frequency.size()>=m)answer=Math.max(answer,sum);
        }
        return answer;
    }
}

